-- Rebuild Medina Book 4 lesson 15 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 60-64. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '15';
  if existing_count <> 9 then
    raise exception 'Expected 9 Book 4 lesson 15 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'الِاسْتِثْنَاءُ وَأَقْسَامُهُ (исключение и его виды)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْتِثْنَاءُ إِخْرَاجُ مَا بَعْدَ أَدَاةِ الِاسْتِثْنَاءِ مِنْ حُكْمِ مَا قَبْلَهَا. وَلَهُ ثَلَاثَةُ أَرْكَانٍ: الْمُسْتَثْنَى مِنْهُ، وَأَدَاةُ الِاسْتِثْنَاءِ، وَالْمُسْتَثْنَى. وَمِنْ أَدَوَاتِهِ: إِلَّا، وَغَيْرٌ، وَسِوَى، وَمَا عَدَا، وَمَا خَلَا. وَهُوَ مُتَّصِلٌ أَوْ مُنْقَطِعٌ؛ وَيَكُونُ تَامًّا أَوْ مُفَرَّغًا، وَمُوجَبًا أَوْ غَيْرَ مُوجَبٍ.</span><p class="rule-study-text">Исключение выводит слово после орудия исключения из правила, относящегося к предшествующей части. Шарх определяет три элемента конструкции, основные орудия и различия между связанным, разорванным, полным, неполным, утвердительным и неутвердительным исключением.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три элемента исключения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الرُّكْنُ</span><span class="rule-table-ru">элемент</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">часть примера</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русское значение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُسْتَثْنَى مِنْهُ</span><span class="rule-table-ru">множество, из которого исключают</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">نَجَحَ الطُّلَّابُ</span><span class="rule-table-ru">студенты успешно сдали</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الطُّلَّابُ</span><span class="rule-table-ru">общее множество</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَدَاةُ الِاسْتِثْنَاءِ</span><span class="rule-table-ru">орудие исключения</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِلَّا</span><span class="rule-table-ru">кроме</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِلَّا</span><span class="rule-table-ru">связывает общее множество с исключаемым</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمُسْتَثْنَى</span><span class="rule-table-ru">исключаемое</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">طَالِبًا مِنْهُمْ</span><span class="rule-table-ru">одного студента из них</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">طَالِبًا</span><span class="rule-table-ru">слово, исключённое из общего правила</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Названные в шархе орудия</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْأَدَاةُ</span><span class="rule-table-ru">орудие</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُهَا</span><span class="rule-table-ru">часть речи</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِلَّا</span><span class="rule-table-ru">кроме</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفٌ</span><span class="rule-table-ru">частица</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَدَاةُ اسْتِثْنَاءٍ</span><span class="rule-table-ru">орудие исключения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">غَيْرٌ، سِوَى</span><span class="rule-table-ru">кроме, за исключением</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمَانِ</span><span class="rule-table-ru">два имени</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُضَافَانِ إِلَى الْمُسْتَثْنَى</span><span class="rule-table-ru">употребляются в идафе с исключаемым</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَا عَدَا، مَا خَلَا</span><span class="rule-table-ru">за исключением</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلَانِ</span><span class="rule-table-ru">два глагола</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَنْصِبَانِ الْمُسْتَثْنَى</span><span class="rule-table-ru">ставят исключаемое в винительный падеж</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Основные виды</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">التَّعْرِيفُ</span><span class="rule-table-ru">определение</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُتَّصِلٌ</span><span class="rule-table-ru">связанное исключение</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمُسْتَثْنَى بَعْضٌ مِنَ الْمُسْتَثْنَى مِنْهُ</span><span class="rule-table-ru">исключаемое является частью общего множества</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">حَضَرَ الْمُدَرِّسُونَ إِلَّا مُدَرِّسًا مِنْهُمْ؛ حَفِظْتُ الْقُرْآنَ إِلَّا سُورَةَ الْبَقَرَةِ.</span><span class="rule-table-ru">Учителя пришли, кроме одного из них; я выучил Коран, кроме суры «аль-Бакара».</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَامٌّ مُوجَبٌ</span><span class="rule-table-ru">полное утвердительное</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">ذُكِرَ الْمُسْتَثْنَى مِنْهُ وَلَمْ يَسْبِقْ نَهْيٌ وَلَا نَفْيٌ وَلَا اسْتِفْهَامٌ</span><span class="rule-table-ru">общее множество названо, а отрицания, запрета или вопроса перед ним нет</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">نَجَحَ الطُّلَّابُ إِلَّا طَالِبًا مِنْهُمْ.</span><span class="rule-table-ru">Студенты успешно сдали, кроме одного.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَامٌّ غَيْرُ مُوجَبٍ</span><span class="rule-table-ru">полное неутвердительное</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">ذُكِرَ الْمُسْتَثْنَى مِنْهُ وَسَبَقَ نَهْيٌ أَوْ نَفْيٌ أَوِ اسْتِفْهَامٌ</span><span class="rule-table-ru">общее множество названо после запрета, отрицания или вопроса</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا نَجَحَ الطُّلَّابُ إِلَّا طَالِبًا مِنْهُمْ؛ هَلْ نَجَحَ الطُّلَّابُ إِلَّا إِيَّاكَ؟ لَا تَسْأَلْ أَحَدًا إِلَّا الْمُدَرِّسَ.</span><span class="rule-table-ru">Студенты не сдали, кроме одного; разве студенты сдали, кроме тебя? Не спрашивай никого, кроме учителя.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُفَرَّغٌ</span><span class="rule-table-ru">неполное, или опустошённое</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">حُذِفَ الْمُسْتَثْنَى مِنْهُ، وَلَا يَكُونُ إِلَّا غَيْرَ مُوجَبٍ</span><span class="rule-table-ru">общее множество опущено; такой вид бывает только неутвердительным</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا حَضَرَ إِلَّا عَلِيٌّ؛ لَا تَسْأَلْ إِلَّا خَالِدًا؛ هَلْ مَرَرْتَ إِلَّا بِعَلِيٍّ؟</span><span class="rule-table-ru">Пришёл только Али; спрашивай только Халида; разве ты проходил мимо кого-либо, кроме Али?</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُنْقَطِعٌ</span><span class="rule-table-ru">разорванное исключение</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمُسْتَثْنَى لَيْسَ بَعْضًا مِنَ الْمُسْتَثْنَى مِنْهُ</span><span class="rule-table-ru">исключаемое не является частью общего множества</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">حَضَرَ الطُّلَّابُ إِلَّا الْمُدَرِّسِينَ؛ أَكَلْتُ الطَّعَامَ إِلَّا الدَّوَاءَ.</span><span class="rule-table-ru">Пришли студенты, но не учителя; я принял пищу, но не лекарство.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры четырёх видов</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلٗا مِّنۡهُمۡ﴾</span><span class="rule-example-ru">И они выпили из неё, кроме немногих из них: связанное полное утвердительное исключение.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿مَّا فَعَلُوهُ إِلَّا قَلِيلٞ مِّنۡهُمۡ﴾</span><span class="rule-example-ru">Они не сделали бы этого, кроме немногих из них: связанное полное неутвердительное исключение.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿هَلۡ جَزَآءُ ٱلۡإِحۡسَٰنِ إِلَّا ٱلۡإِحۡسَٰنُ﴾</span><span class="rule-example-ru">Есть ли воздаяние за добро, кроме добра? Общее множество не названо, поэтому исключение неполное.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿لَّا يَسۡمَعُونَ فِيهَا لَغۡوًا إِلَّا سَلَٰمٗا﴾</span><span class="rule-example-ru">Они не услышат там празднословия, кроме приветствия миром: приветствие не является частью празднословия, поэтому исключение разорванное.</span></div></div></div></div>', 'Исключение выводит слово после орудия исключения из правила, относящегося к предшествующей части. Шарх определяет три элемента конструкции, основные орудия и различия между связанным, разорванным, полным, неполным, утвердительным и неутвердительным исключением.', 'الِاسْتِثْنَاءُ إِخْرَاجُ مَا بَعْدَ أَدَاةِ الِاسْتِثْنَاءِ مِنْ حُكْمِ مَا قَبْلَهَا. وَلَهُ ثَلَاثَةُ أَرْكَانٍ: الْمُسْتَثْنَى مِنْهُ، وَأَدَاةُ الِاسْتِثْنَاءِ، وَالْمُسْتَثْنَى. وَمِنْ أَدَوَاتِهِ: إِلَّا، وَغَيْرٌ، وَسِوَى، وَمَا عَدَا، وَمَا خَلَا. وَهُوَ مُتَّصِلٌ أَوْ مُنْقَطِعٌ؛ وَيَكُونُ تَامًّا أَوْ مُفَرَّغًا، وَمُوجَبًا أَوْ غَيْرَ مُوجَبٍ.'),
    (2, 'حُكْمُ الْمُسْتَثْنَى بِإِلَّا فِي الِاسْتِثْنَاءِ الْمُتَّصِلِ (разбор исключаемого с إِلَّا в связанном исключении)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">إِذَا كَانَ الِاسْتِثْنَاءُ الْمُتَّصِلُ تَامًّا مُوجَبًا، وَجَبَ نَصْبُ الْمُسْتَثْنَى بِإِلَّا. وَإِذَا كَانَ تَامًّا غَيْرَ مُوجَبٍ، جَازَ فِيهِ النَّصْبُ عَلَى الِاسْتِثْنَاءِ، وَالْإِتْبَاعُ عَلَى الْبَدَلِيَّةِ، وَالْإِتْبَاعُ أَفْصَحُ.</span><p class="rule-study-text">В полном утвердительном связанном исключении исключаемое обязательно стоит в винительном падеже. В полном неутвердительном допустимы винительный как исключаемое и согласование с предшествующим словом как بَدَلٌ; второй вариант красноречивее.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два правила управления</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَالُ الِاسْتِثْنَاءِ</span><span class="rule-table-ru">тип конструкции</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">правило</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ وَالْإِعْرَابُ</span><span class="rule-table-ru">пример и разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُتَّصِلٌ تَامٌّ مُوجَبٌ</span><span class="rule-table-ru">связанное полное утвердительное</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">وُجُوبُ النَّصْبِ</span><span class="rule-table-ru">винительный обязателен</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">نَجَحَ الطُّلَّابُ إِلَّا طَالِبًا مِنْهُمْ؛ طَالِبًا: مُسْتَثْنًى مَنْصُوبٌ.</span><span class="rule-table-ru">Студенты сдали, кроме одного; طَالِبًا — исключаемое в винительном падеже.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُتَّصِلٌ تَامٌّ غَيْرُ مُوجَبٍ</span><span class="rule-table-ru">связанное полное неутвердительное</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">جَوَازُ النَّصْبِ وَالْإِتْبَاعِ</span><span class="rule-table-ru">допустимы винительный и согласование</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا نَجَحَ الطُّلَّابُ إِلَّا طَالِبًا مِنْهُمْ؛ طَالِبًا: مُسْتَثْنًى جَائِزُ النَّصْبِ.</span><span class="rule-table-ru">Студенты не сдали, кроме одного; طَالِبًا — исключаемое с допустимым винительным.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْإِتْبَاعُ فِي الرَّفْعِ</span><span class="rule-table-ru">согласование в именительном</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">بَدَلُ بَعْضٍ مِنْ كُلٍّ</span><span class="rule-table-ru">замена части вместо целого</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَا نَجَحَ الطُّلَّابُ إِلَّا طَالِبٌ مِنْهُمْ؛ طَالِبٌ: بَدَلٌ مَرْفُوعٌ.</span><span class="rule-table-ru">Студенты не сдали, кроме одного; طَالِبٌ — замена в именительном падеже.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْإِتْبَاعُ فِي الْجَرِّ</span><span class="rule-table-ru">согласование в родительном</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">بَدَلُ بَعْضٍ مِنْ كُلٍّ</span><span class="rule-table-ru">замена части вместо целого</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَا مَرَرْتُ بِأَحَدٍ إِلَّا طَالِبٍ مِنْهُمْ؛ طَالِبٍ: بَدَلٌ مَجْرُورٌ.</span><span class="rule-table-ru">Я не прошёл ни мимо кого, кроме одного студента; طَالِبٍ — замена в родительном падеже.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْإِتْبَاعُ فِي النَّصْبِ</span><span class="rule-table-ru">согласование в винительном</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مُسْتَثْنًى أَوْ بَدَلٌ</span><span class="rule-table-ru">исключаемое либо замена</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">هَلْ سَأَلْتَ الطُّلَّابَ إِلَّا حَامِدًا؟ حَامِدًا: مُسْتَثْنًى مَنْصُوبٌ أَوْ بَدَلٌ مَنْصُوبٌ.</span><span class="rule-table-ru">Ты спрашивал студентов, кроме Хамида? حَامِدًا можно разобрать как исключаемое или как замену в винительном.</span></td></tr></tbody></table></div></div></div>', 'В полном утвердительном связанном исключении исключаемое обязательно стоит в винительном падеже. В полном неутвердительном допустимы винительный как исключаемое и согласование с предшествующим словом как بَدَلٌ; второй вариант красноречивее.', 'إِذَا كَانَ الِاسْتِثْنَاءُ الْمُتَّصِلُ تَامًّا مُوجَبًا، وَجَبَ نَصْبُ الْمُسْتَثْنَى بِإِلَّا. وَإِذَا كَانَ تَامًّا غَيْرَ مُوجَبٍ، جَازَ فِيهِ النَّصْبُ عَلَى الِاسْتِثْنَاءِ، وَالْإِتْبَاعُ عَلَى الْبَدَلِيَّةِ، وَالْإِتْبَاعُ أَفْصَحُ.'),
    (3, 'حُكْمُ الْمُسْتَثْنَى بِإِلَّا فِي الِاسْتِثْنَاءِ الْمُنْقَطِعِ (исключаемое с إِلَّا в разорванном исключении)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">يَجِبُ نَصْبُ الْمُسْتَثْنَى بِإِلَّا فِي الِاسْتِثْنَاءِ الْمُنْقَطِعِ فِي جَمِيعِ أَحْوَالِهِ، سَوَاءٌ أَكَانَ الْكَلَامُ مُوجَبًا أَمْ غَيْرَ مُوجَبٍ.</span><p class="rule-study-text">В разорванном исключении слово после إِلَّا обязательно стоит в винительном падеже и в утвердительном, и в неутвердительном предложении.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Одинаковое управление в двух контекстах</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">السِّيَاقُ</span><span class="rule-table-ru">контекст</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُوجَبٌ</span><span class="rule-table-ru">утвердительное</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">حَضَرَ الْمُدَرِّسُونَ إِلَّا الطُّلَّابَ.</span><span class="rule-table-ru">Пришли учителя, но не студенты.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الطُّلَّابَ: مُسْتَثْنًى مَنْصُوبٌ.</span><span class="rule-table-ru">الطُّلَّابَ — исключаемое в винительном падеже.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">غَيْرُ مُوجَبٍ</span><span class="rule-table-ru">неутвердительное</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا حَضَرَ الْمُدَرِّسُونَ إِلَّا الطُّلَّابَ.</span><span class="rule-table-ru">Не пришли учителя, но студенты пришли.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الطُّلَّابَ: مُسْتَثْنًى مَنْصُوبٌ.</span><span class="rule-table-ru">الطُّلَّابَ — исключаемое в винительном падеже.</span></td></tr></tbody></table></div></div></div>', 'В разорванном исключении слово после إِلَّا обязательно стоит в винительном падеже и в утвердительном, и в неутвердительном предложении.', 'يَجِبُ نَصْبُ الْمُسْتَثْنَى بِإِلَّا فِي الِاسْتِثْنَاءِ الْمُنْقَطِعِ فِي جَمِيعِ أَحْوَالِهِ، سَوَاءٌ أَكَانَ الْكَلَامُ مُوجَبًا أَمْ غَيْرَ مُوجَبٍ.'),
    (4, 'حُكْمُ الِاسْتِثْنَاءِ الْمُفَرَّغِ (разбор неполного исключения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">فِي الِاسْتِثْنَاءِ الْمُفَرَّغِ يُحْذَفُ الْمُسْتَثْنَى مِنْهُ، وَلَا يَكُونُ هَذَا الِاسْتِثْنَاءُ إِلَّا غَيْرَ مُوجَبٍ. وَيُعْرَبُ مَا بَعْدَ إِلَّا بِحَسَبِ مَا يَطْلُبُهُ الْعَامِلُ، وَتَكُونُ إِلَّا مُلْغَاةً مِنَ النَّاحِيَةِ الْإِعْرَابِيَّةِ.</span><p class="rule-study-text">В неполном исключении общее множество опущено, конструкция бывает только неутвердительной, а слово после إِلَّا получает тот падеж и ту функцию, которых требует глагол или другой управляющий элемент.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор по требованию управляющего элемента</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَظِيفَةُ</span><span class="rule-table-ru">функция</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-table-ru">субъект</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا جَاءَ إِلَّا عَلِيٌّ.</span><span class="rule-table-ru">Пришёл только Али.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَلِيٌّ: فَاعِلٌ مَرْفُوعٌ.</span><span class="rule-table-ru">عَلِيٌّ — субъект в именительном падеже.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-table-ru">прямое дополнение</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">لَا تَسْأَلْ إِلَّا خَالِدًا.</span><span class="rule-table-ru">Спрашивай только Халида.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">خَالِدًا: مَفْعُولٌ بِهِ مَنْصُوبٌ.</span><span class="rule-table-ru">خَالِدًا — прямое дополнение в винительном падеже.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">اسْمٌ مَجْرُورٌ</span><span class="rule-table-ru">имя в родительном</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا مَرَرْتُ إِلَّا بِخَالِدٍ.</span><span class="rule-table-ru">Я прошёл только мимо Халида.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">خَالِدٍ: اسْمٌ مَجْرُورٌ بِالْبَاءِ.</span><span class="rule-table-ru">خَالِدٍ — имя в родительном после بِـ.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ كَانَ</span><span class="rule-table-ru">сказуемое كَانَ</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا كُنْتُ إِلَّا طَالِبًا.</span><span class="rule-table-ru">Я был только студентом.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">طَالِبًا: خَبَرُ كَانَ مَنْصُوبٌ.</span><span class="rule-table-ru">طَالِبًا — сказуемое كَانَ в винительном падеже.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">حَالٌ</span><span class="rule-table-ru">обстоятельство состояния</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا جِئْتُ إِلَّا مَاشِيًا.</span><span class="rule-table-ru">Я пришёл только пешком.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَاشِيًا: حَالٌ مَنْصُوبَةٌ.</span><span class="rule-table-ru">مَاشِيًا — обстоятельство состояния в винительном падеже.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Роль إِلَّا</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">إِلَّا مُلْغَاةٌ مِنَ النَّاحِيَةِ الْإِعْرَابِيَّةِ</span><span class="rule-term-ru">с точки зрения синтаксического управления إِلَّا считается как бы отсутствующей</span></div></div></div></div>', 'В неполном исключении общее множество опущено, конструкция бывает только неутвердительной, а слово после إِلَّا получает тот падеж и ту функцию, которых требует глагол или другой управляющий элемент.', 'فِي الِاسْتِثْنَاءِ الْمُفَرَّغِ يُحْذَفُ الْمُسْتَثْنَى مِنْهُ، وَلَا يَكُونُ هَذَا الِاسْتِثْنَاءُ إِلَّا غَيْرَ مُوجَبٍ. وَيُعْرَبُ مَا بَعْدَ إِلَّا بِحَسَبِ مَا يَطْلُبُهُ الْعَامِلُ، وَتَكُونُ إِلَّا مُلْغَاةً مِنَ النَّاحِيَةِ الْإِعْرَابِيَّةِ.'),
    (5, 'حُكْمُ الْمُسْتَثْنَى بِغَيْرٍ وَسِوَى (исключение через غَيْرٌ и سِوَى)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">الْمُسْتَثْنَى بِغَيْرٍ وَسِوَى مَجْرُورٌ بِالْإِضَافَةِ دَائِمًا، وَتُعْرَبُ غَيْرٌ وَسِوَى إِعْرَابَ الْمُسْتَثْنَى بِإِلَّا.</span><p class="rule-study-text">Исключаемое после غَيْرٌ и سِوَى всегда является вторым членом идафы и стоит в родительном падеже. Сами غَيْرٌ и سِوَى получают тот разбор, который получило бы исключаемое после إِلَّا.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Полное исключение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">السِّيَاقُ</span><span class="rule-table-ru">контекст</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِعْرَابُ غَيْرٍ وَمَا بَعْدَهَا</span><span class="rule-table-ru">разбор غَيْرٌ и следующего слова</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَامٌّ مُوجَبٌ</span><span class="rule-table-ru">полное утвердительное</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">نَجَحَ الطُّلَّابُ غَيْرَ طَالِبٍ.</span><span class="rule-table-ru">Студенты сдали, кроме одного.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">غَيْرَ: مُسْتَثْنًى وَاجِبُ النَّصْبِ؛ طَالِبٍ: مُضَافٌ إِلَيْهِ مَجْرُورٌ.</span><span class="rule-table-ru">غَيْرَ — обязательно винительное исключаемое; طَالِبٍ — второй член идафы в родительном.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَامٌّ غَيْرُ مُوجَبٍ</span><span class="rule-table-ru">полное неутвердительное</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا نَجَحَ الطُّلَّابُ غَيْرُ طَالِبٍ؛ وَيَجُوزُ غَيْرَ طَالِبٍ.</span><span class="rule-table-ru">Студенты не сдали, кроме одного; допустимо также غَيْرَ طَالِبٍ.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">غَيْرُ: بَدَلٌ مَرْفُوعٌ، أَوْ غَيْرَ: مُسْتَثْنًى مَنْصُوبٌ؛ طَالِبٍ: مُضَافٌ إِلَيْهِ مَجْرُورٌ.</span><span class="rule-table-ru">غَيْرُ — замена в именительном, либо غَيْرَ — исключаемое в винительном; طَالِبٍ всегда в родительном.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Неполное исключение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَظِيفَةُ</span><span class="rule-table-ru">функция غَيْرٌ</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فَاعِلٌ مَرْفُوعٌ</span><span class="rule-table-ru">субъект в именительном</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا جَاءَ غَيْرُ عَلِيٍّ.</span><span class="rule-table-ru">Не пришёл никто, кроме Али.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">غَيْرُ: فَاعِلٌ مَرْفُوعٌ؛ عَلِيٍّ: مُضَافٌ إِلَيْهِ مَجْرُورٌ.</span><span class="rule-table-ru">غَيْرُ — субъект; عَلِيٍّ — второй член идафы.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَفْعُولٌ بِهِ مَنْصُوبٌ</span><span class="rule-table-ru">прямое дополнение в винительном</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">لَا تَسْأَلْ غَيْرَ عَلِيٍّ.</span><span class="rule-table-ru">Не спрашивай никого, кроме Али.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">غَيْرَ: مَفْعُولٌ بِهِ مَنْصُوبٌ؛ عَلِيٍّ: مُضَافٌ إِلَيْهِ مَجْرُورٌ.</span><span class="rule-table-ru">غَيْرَ — прямое дополнение; عَلِيٍّ — второй член идафы.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">اسْمٌ مَجْرُورٌ</span><span class="rule-table-ru">имя в родительном</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا مَرَرْتُ بِغَيْرِ عَلِيٍّ.</span><span class="rule-table-ru">Я не прошёл ни мимо кого, кроме Али.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">غَيْرِ: اسْمٌ مَجْرُورٌ بِالْبَاءِ؛ عَلِيٍّ: مُضَافٌ إِلَيْهِ مَجْرُورٌ.</span><span class="rule-table-ru">غَيْرِ — имя после предлога; عَلِيٍّ — второй член идафы.</span></td></tr></tbody></table></div></div></div>', 'Исключаемое после غَيْرٌ и سِوَى всегда является вторым членом идафы и стоит в родительном падеже. Сами غَيْرٌ и سِوَى получают тот разбор, который получило бы исключаемое после إِلَّا.', 'الْمُسْتَثْنَى بِغَيْرٍ وَسِوَى مَجْرُورٌ بِالْإِضَافَةِ دَائِمًا، وَتُعْرَبُ غَيْرٌ وَسِوَى إِعْرَابَ الْمُسْتَثْنَى بِإِلَّا.'),
    (6, 'حُكْمُ الْمُسْتَثْنَى بِمَا خَلَا وَمَا عَدَا (исключение через مَا خَلَا и مَا عَدَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">مَا خَلَا وَمَا عَدَا فِعْلَانِ مَاضِيَانِ جَامِدَانِ، وَالْمُسْتَثْنَى بَعْدَهُمَا مَفْعُولٌ بِهِ مَنْصُوبٌ. وَفَاعِلُ كُلٍّ مِنْهُمَا ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ، يَعُودُ إِلَى كَلِمَةِ «بَعْضٍ» الْمَفْهُومَةِ مِنَ الْجُمْلَةِ.</span><p class="rule-study-text">مَا خَلَا и مَا عَدَا — два неизменяемых по времени прошедших глагола. Исключаемое после них разбирается как прямое дополнение в винительном падеже, а скрытый субъект هُوَ возвращается к подразумеваемому слову «часть».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и полный разбор исключаемого</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَدَاةُ</span><span class="rule-table-ru">конструкция</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَا خَلَا</span><span class="rule-table-ru">за исключением</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">قَرَأْتُ الْكُتُبَ مَا خَلَا كِتَابًا.</span><span class="rule-table-ru">Я прочитал книги, кроме одной.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">كِتَابًا: مَفْعُولٌ بِهِ مَنْصُوبٌ؛ وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ.</span><span class="rule-table-ru">كِتَابًا — прямое дополнение в винительном; субъект глагола — скрытое هُوَ.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَا عَدَا</span><span class="rule-table-ru">за исключением</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">كَافَأْتُ الطُّلَّابَ مَا عَدَا طَالِبًا.</span><span class="rule-table-ru">Я наградил студентов, кроме одного.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">طَالِبًا: مَفْعُولٌ بِهِ مَنْصُوبٌ؛ وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ.</span><span class="rule-table-ru">طَالِبًا — прямое дополнение в винительном; субъект глагола — скрытое هُوَ.</span></td></tr></tbody></table></div></div></div>', 'مَا خَلَا и مَا عَدَا — два неизменяемых по времени прошедших глагола. Исключаемое после них разбирается как прямое дополнение в винительном падеже, а скрытый субъект هُوَ возвращается к подразумеваемому слову «часть».', 'مَا خَلَا وَمَا عَدَا فِعْلَانِ مَاضِيَانِ جَامِدَانِ، وَالْمُسْتَثْنَى بَعْدَهُمَا مَفْعُولٌ بِهِ مَنْصُوبٌ. وَفَاعِلُ كُلٍّ مِنْهُمَا ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ، يَعُودُ إِلَى كَلِمَةِ «بَعْضٍ» الْمَفْهُومَةِ مِنَ الْجُمْلَةِ.'),
    (7, 'الضَّمِيرُ الْوَاقِعُ خَبَرًا لِكَانَ (местоимение в роли сказуемого كَانَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا وَقَعَ الضَّمِيرُ خَبَرًا لِكَانَ، جَازَ فِيهِ الْوَصْلُ وَالْفَصْلُ؛ فَيَأْتِي ضَمِيرًا مُتَّصِلًا أَوْ ضَمِيرَ نَصْبٍ مُنْفَصِلًا.</span><p class="rule-study-text">Если местоимение является сказуемым كَانَ, его разрешено присоединить к глаголу либо употребить отдельно в форме винительного местоимения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два допустимых оформления</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَجْهُ</span><span class="rule-table-ru">вариант</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَصْلُ</span><span class="rule-table-ru">слитное местоимение</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَخْشَى أَنْ أَكُونَهُ؛ الصَّدِيقُ كُنْتَهُ.</span><span class="rule-table-ru">Боюсь оказаться им; ты был тем другом.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">ـهُ: ضَمِيرٌ مُتَّصِلٌ</span><span class="rule-table-ru">ـهُ присоединено к форме كَانَ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفَصْلُ</span><span class="rule-table-ru">отдельное местоимение</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَخْشَى أَنْ أَكُونَ إِيَّاهُ؛ الصَّدِيقُ كُنْتَ إِيَّاهُ.</span><span class="rule-table-ru">Боюсь оказаться им; ты был именно тем другом.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِيَّاهُ: ضَمِيرُ نَصْبٍ مُنْفَصِلٌ</span><span class="rule-table-ru">إِيَّاهُ употреблено отдельно</span></td></tr></tbody></table></div></div></div>', 'Если местоимение является сказуемым كَانَ, его разрешено присоединить к глаголу либо употребить отдельно в форме винительного местоимения.', 'إِذَا وَقَعَ الضَّمِيرُ خَبَرًا لِكَانَ، جَازَ فِيهِ الْوَصْلُ وَالْفَصْلُ؛ فَيَأْتِي ضَمِيرًا مُتَّصِلًا أَوْ ضَمِيرَ نَصْبٍ مُنْفَصِلًا.'),
    (8, 'أَلَا حَرْفُ اسْتِفْتَاحٍ وَتَنْبِيهٍ (أَلَا как частица начала речи и привлечения внимания)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">أَلَا حَرْفُ اسْتِفْتَاحٍ وَتَنْبِيهٍ، مَبْنِيٌّ عَلَى السُّكُونِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><p class="rule-study-text">Частица أَلَا открывает высказывание и привлекает внимание слушателя. Она неизменяема с сукуном и не занимает синтаксической позиции.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Значение и разбор</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ اسْتِفْتَاحٍ</span><span class="rule-term-ru">частица начала высказывания</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ تَنْبِيهٍ</span><span class="rule-term-ru">частица привлечения внимания</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى السُّكُونِ</span><span class="rule-term-ru">неизменяема с сукуном</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ</span><span class="rule-term-ru">не имеет синтаксической позиции</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿أَلَآ إِنَّهُمۡ هُمُ ٱلسُّفَهَآءُ﴾</span><span class="rule-example-ru">Знайте: поистине, именно они — глупцы.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ﴾</span><span class="rule-example-ru">Знайте: только поминанием Аллаха успокаиваются сердца.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Пример шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">أَلَا إِنَّ الْمُؤْمِنِينَ هُمُ الْمُفْلِحُونَ.</span><span class="rule-example-ru">Знайте: поистине, верующие — преуспевшие.</span></div></div></div></div>', 'Частица أَلَا открывает высказывание и привлекает внимание слушателя. Она неизменяема с сукуном и не занимает синтаксической позиции.', 'أَلَا حَرْفُ اسْتِفْتَاحٍ وَتَنْبِيهٍ، مَبْنِيٌّ عَلَى السُّكُونِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.'),
    (9, 'جَمْعُ دِينَارٍ عَلَى غَيْرِ قِيَاسٍ (множественное число دِينَارٌ не по обычной аналогии)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">جَمْعُ دِينَارٍ عَلَى دَنَانِيرَ سَمَاعِيٌّ عَلَى غَيْرِ قِيَاسٍ؛ وَالْقِيَاسُ دَيَانِيرُ. وَمِثْلُهُ: دِيوَانٌ ـ دَوَاوِينُ، وَالْقِيَاسُ دَيَاوِينُ؛ وَقِيرَاطٌ ـ قَرَارِيطُ، وَالْقِيَاسُ قَيَارِيطُ؛ وَدِيمَاسٌ ـ دَمَامِيسُ، وَالْقِيَاسُ دَيَامِيسُ.</span><p class="rule-study-text">Слово دِينَارٌ образует закреплённое употреблением множественное دَنَانِيرُ вместо ожидаемого по аналогии دَيَانِيرُ. Шарх приводит ещё три подобных ряда.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Употребительная и ожидаемая формы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ</span><span class="rule-table-ru">единственное число</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْجَمْعُ عَلَى غَيْرِ قِيَاسٍ</span><span class="rule-table-ru">употребительное множественное</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْجَمْعُ عَلَى الْقِيَاسِ</span><span class="rule-table-ru">ожидаемая форма по аналогии</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русское значение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">دِينَارٌ</span><span class="rule-table-ru">динар</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">دَنَانِيرُ</span><span class="rule-table-ru">динары — употребительная форма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">دَيَانِيرُ</span><span class="rule-table-ru">ожидаемая, но не принятая здесь форма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">نَقْدٌ</span><span class="rule-table-ru">денежная единица</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">دِيوَانٌ</span><span class="rule-table-ru">реестр или сборник</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">دَوَاوِينُ</span><span class="rule-table-ru">реестры или сборники — употребительная форма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">دَيَاوِينُ</span><span class="rule-table-ru">ожидаемая форма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">سِجِلٌّ أَوْ مَجْمُوعَةٌ</span><span class="rule-table-ru">реестр или сборник</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قِيرَاطٌ</span><span class="rule-table-ru">кират, карат</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">قَرَارِيطُ</span><span class="rule-table-ru">кираты — употребительная форма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">قَيَارِيطُ</span><span class="rule-table-ru">ожидаемая форма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مِقْدَارٌ مَعْرُوفٌ</span><span class="rule-table-ru">известная мера — кират</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">دِيمَاسٌ</span><span class="rule-table-ru">димас, подземное помещение</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">دَمَامِيسُ</span><span class="rule-table-ru">димасы — употребительная форма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">دَيَامِيسُ</span><span class="rule-table-ru">ожидаемая форма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَكَانٌ تَحْتَ الْأَرْضِ</span><span class="rule-table-ru">подземное помещение</span></td></tr></tbody></table></div></div></div>', 'Слово دِينَارٌ образует закреплённое употреблением множественное دَنَانِيرُ вместо ожидаемого по аналогии دَيَانِيرُ. Шарх приводит ещё три подобных ряда.', 'جَمْعُ دِينَارٍ عَلَى دَنَانِيرَ سَمَاعِيٌّ عَلَى غَيْرِ قِيَاسٍ؛ وَالْقِيَاسُ دَيَانِيرُ. وَمِثْلُهُ: دِيوَانٌ ـ دَوَاوِينُ، وَالْقِيَاسُ دَيَاوِينُ؛ وَقِيرَاطٌ ـ قَرَارِيطُ، وَالْقِيَاسُ قَيَارِيطُ؛ وَدِيمَاسٌ ـ دَمَامِيسُ، وَالْقِيَاسُ دَيَامِيسُ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '15'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '15'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ الْخَامِسَ عَشَرَ
الاِسْتِثْنَاءُ
الاستثناءُ : إِخْرَاجُ مَا بَعْدَ أَدَاةِ الاسْتِثْنَاءِ مِنْ حُكْمِ ما قَبْلَهَا .
أَرْكَانُهُ : ثلاثة , هي : المستثنَى مِنْهُ , وأداةُ الاستثناءِ , والمستثنَى .
نحو : نجحَ الطُّلابُ              إِلاَّ             طالباً منهم .
المستثنى منه       أداة الاستثناء       المستثنى
أدواته كثيرة , منها :
1- إلاَّ : حرف .
2- غَيْرُ ، وسِوَى : اسمان .
3- مَا عَدَا ، ومَا خَلَا : فعلان .
أقسامُه : مُتَّصِلٌ ، وَمُنْقَطِعٌ .
1- الْمُتَّصِلُ : هو ما كان المستثنى بعضاً من المستثنى منه .
نحو : حَضَرَ المدرسون إلاَّ مدرساً منهم . حفظت القرآن إلا سورةَ البقرةِ .
وهو قسمان :
أ- مُتَّصِلٌ تَامٌّ مُوجَبٌ .                        ب- مُتَّصِلٌ تَامٌّ غَيْرُ مُوجَبٍ .
* فإذا ذُكر المستثنى منه فهو تامٌّ ، وإذا لم يسبق بنهي , أو نفي , أو استفهام فهو موجبٌ.
نحو : نجحَ الطُّلابُ إلا طالباً منهم ( متصل تام موجب ) ومنه قوله تعالى :
﴿ فَشَرِبُوا مِنْهُ إِلَّا قَلِيلًا مِنْهُمْ ﴾ .
* أما إذا سُبِق بنهي , أو نفي , أو استفهام فهو غير موجب , نحو : ما نجح الطلابُ إلا طالباً منهم . هل نجح الطلابُ إلا إيَّاكَ ؟ لا تسأل أحداً إلا المدرسَ . ومنه قوله تعالى :
﴿ مَا فَعَلُوهُ إِلَّا قَلِيلٌ مِنْهُمْ ﴾ . ( هذه الأمثلة مُتَّصِلَةٌ تَامَّةٌ غيرُ موجبةٍ ) .
* وإذا حُذف المستثنى منه سُمِّيَ الاستثناءُ حينئذٍ مُفَرَّغاً ،ولا يكونُ المفرَّغُ إلا غَيْرَ مُوجَبٍ،   نحو : ما حضر إلا عليٌّ . لا تسألْ إلا خالداً . هل مررت إلا بعليٍّ ؟ ومنه قوله تعالى : ﴿ هَلْ جَزَاءُ الْإِحْسَانِ إِلَّا الْإِحْسَانُ ﴾ .
2- الْمُنْقَطِعُ : هو ما لم يكن المستثنى بعضاً من المستثنى منه ، نحو : حضر الطلابُ إلا المدرسين . أكلت الطعامَ إلا الدواءَ . ومنه قوله تعالى : ﴿ لَا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَامًا ﴾ .
ويكون تاماًّ مُوجَباً كما في الأمثلة السابقة , ويكون تامًّا غيرَ موجبٍ ، نحو :              ما حضر الطلابُ إلا المدرسين .', 60, 61, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '15' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'حكمُ المستثنى بـ ( إِلاَّ ) في الاستثناءِ الْمُتَّصِلِ
1- يجبُ نصبُه , وذلك إذا كان متصلا تاماًّ مُوجباً , نحو : نجح الطلاب إلا طالباً منهم .
2- يجوزُ النَّصْبُ ، والإتْبَاعُ ( على أنه بَدَلُ بَعْضٍ مِنْ كُلّ , وهو الأَفْصَحُ ) وذلك إذا كان متَّصلا تاماًّ غيرَ موجب .
نحو : ما نجح الطلابُ إِلاَّ طالباً منهم : مستثنى جائز النَّصب .
ويجوز : ما نجح الطلابُ إِلاَّ طالبٌ منهم : بدل مرفوع .
ونحو : ما مررتُ بِأحدٍ إِلاَّ طالباً منهم . ويجوز : إِلاَّ طالبٍ : بدل مجرور .
ونحو : هل سألتَ الطلابَ إلا حامداً ( بالنَّصب على أنه مستثنى منصوب ، أو بدل منصوب ) .', 61, 62, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '15' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'حكمُ المستثنى بـ ( إِلاَّ ) في الاستثناءِ الْمُنْقَطِعِ
يجبُ نصبُه في جميعِ أحوالِهِ .
نحو : حضر المدرسون إلا الطلابَ .        ما حضر المدرسون إلا الطلابَ .
مستثنى منصوب                        مستثنى منصوب', 62, 62, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '15' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'حكمُ المستثنى بـ ( إِلاَّ ) في الاستثناءِ الْمُفَرَّغِ
يُعْرَبُ بِحَسَبِ ما يَطْلُبُهُ العَامِلُ ، نحو : ما جاء إلا عليٌّ ( فاعل مرفوع ) .
ونحو : لا تسألْ إلا خالداً ( مفعول به منصوب ) ما مررتُ إلا بخالدٍ ( اسم مجرور ) .
ونحو : ما كنت إلا طالباً (خبر كان منصوب) ونحو: ما جِئتُ إلا ماشياً (حال منصوبة).
وتكون ( إلاَّ ) مُلْغَاةً من النَّاحيةِ الإعرابيَّةِ ,كأنها غير مذكورةٍ .', 62, 62, 1
from public.rules
